const lessons=[{"sentences":[{"speaker":"A","text":"Hello Mark because we want to learn new recipes I found two interesting cooking classes online.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.907041666666666},{"speaker":"B","text":"That is wonderful news Sarah which options did you look at this morning?","position":2,"audioStartSeconds":6.1070416666666665,"audioEndSeconds":10.480583333333334},{"speaker":"A","text":"The first one is on Tuesday evening and focuses entirely on making homemade pasta from scratch.","position":3,"audioStartSeconds":10.680583333333333,"audioEndSeconds":16.94425},{"speaker":"B","text":"Tuesday evening works well for my schedule although I wonder what equipment we need to bring.","position":4,"audioStartSeconds":17.14425,"audioEndSeconds":22.441416666666665},{"speaker":"A","text":"The teacher provides all the fresh ingredients but students must bring their own sharp kitchen knives.","position":5,"audioStartSeconds":22.641416666666668,"audioEndSeconds":28.646583333333332},{"speaker":"B","text":"Buying professional knives might cost too much money if we only attend this single session.","position":6,"audioStartSeconds":28.846583333333335,"audioEndSeconds":34.28475},{"speaker":"A","text":"We should check the second choice because it has very different rules about kitchen tools.","position":7,"audioStartSeconds":34.48475,"audioEndSeconds":39.76825},{"speaker":"B","text":"Tell me about the second class when you have a free moment to explain the details.","position":8,"audioStartSeconds":39.96825,"audioEndSeconds":44.96825},{"speaker":"A","text":"It takes place on Thursday afternoon and teaches participants how to bake artisan French bread.","position":9,"audioStartSeconds":45.16825,"audioEndSeconds":51.031666666666666},{"speaker":"B","text":"Thursday afternoon is slightly difficult because I usually finish my office work very late.","position":10,"audioStartSeconds":51.23166666666667,"audioEndSeconds":56.73425},{"speaker":"A","text":"The school supplies every single tool including aprons and professional baking pans for everyone.","position":11,"audioStartSeconds":56.93425,"audioEndSeconds":63.39041666666667},{"speaker":"B","text":"Not buying extra equipment sounds extremely attractive since we want to save our money.","position":12,"audioStartSeconds":63.59041666666667,"audioEndSeconds":69.06720833333334},{"speaker":"A","text":"However we still need to solve the scheduling problem before making our final decision.","position":13,"audioStartSeconds":69.26720833333333,"audioEndSeconds":74.47341666666667},{"speaker":"B","text":"Perhaps I can leave my office early on Thursday if I finish important tasks beforehand.","position":14,"audioStartSeconds":74.67341666666667,"audioEndSeconds":80.26620833333334},{"speaker":"A","text":"That compromise sounds brilliant because baking French bread has always been our biggest dream.","position":15,"audioStartSeconds":80.46620833333333,"audioEndSeconds":86.15620833333334},{"speaker":"B","text":"Let us register for the Thursday baking class right now before all available seats disappear.","position":16,"audioStartSeconds":86.35620833333333,"audioEndSeconds":92.16829166666666}],"questions":[{"prompt":"What is the main purpose of the conversation?","options":["To compare two cooking classes and choose one.","To complain about expensive cooking equipment.","To schedule a meeting with a cooking teacher."],"answer":"A","evidenceSentence":1,"evidence":"found two interesting cooking classes online","explanation":"Người nói A mở đầu bằng việc tìm hai lớp học nấu ăn để thảo luận và lựa chọn."},{"prompt":"Why is the first class problematic for Mark?","options":["It is held on a weekend morning.","Students must bring their own knives.","The ingredients are not fresh."],"answer":"B","evidenceSentence":5,"evidence":"students must bring their own sharp kitchen knives","explanation":"Lớp học đầu tiên yêu cầu học viên tự mang dao sắc bén, điều này khiến Mark lo lắng về chi phí."},{"prompt":"What is Mark's initial issue with the Thursday class?","options":["He finishes work too late on that day.","He does not like eating French bread.","He has another class on Thursday evening."],"answer":"A","evidenceSentence":10,"evidence":"I usually finish my office work very late","explanation":"Mark gặp khó khăn với lớp ngày thứ Năm vì anh ấy thường hoàn thành công việc ở văn phòng rất muộn."},{"prompt":"What does speaker A imply about the second class?","options":["It requires expensive professional pans.","It is much cheaper than the first class.","It provides all necessary tools for students."],"answer":"C","evidenceSentence":11,"evidence":"The school supplies every single tool including aprons","explanation":"Lớp thứ hai cung cấp toàn bộ dụng cụ bao gồm cả tạp dề và chảo nướng cho mọi người."},{"prompt":"How do they solve Mark's scheduling problem?","options":["By asking the teacher to change the time.","By planning to leave the office early.","By canceling the cooking lesson completely."],"answer":"B","evidenceSentence":14,"evidence":"leave my office early on Thursday if I finish important tasks","explanation":"Mark đề xuất rời văn phòng sớm vào ngày thứ Năm nếu anh ấy hoàn thành các công việc quan trọng trước."},{"prompt":"What will the speakers do next?","options":["Buy new kitchen knives online.","Call the pasta teacher for details.","Register for the Thursday baking class."],"answer":"C","evidenceSentence":16,"evidence":"register for the Thursday baking class right now","explanation":"Họ quyết định đăng ký lớp học làm bánh mì Pháp vào thứ Năm ngay lập tức."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
